{
  "program": "SCOUT2B_V1_5_K128_AUDIT",
  "date": "2026-08-27",
  "overall_verdict": "EXECUTION_PASS_OBSERVER_LIMITATION_REQUIRES_FIXED_POINT_REFINEMENT",
  "headline": "V1.5 reproducibly finds recurrent one-step transition-refined relational types, but C1 is not a stable future-behavior quotient: exact members of the same C1 can split when successor states are colored by C1 rather than the coarser V1.3 C0.",
  "integrity": {
    "result_bundle_manifest": "PASS_155_FILES",
    "result_bundle_sha256": "28fcc47308e363591b540dfebe43e60b4578da5f62df8d4da006191f93cf6a5d",
    "v15_science_sha256": "08d5f28a3853d53164d48aa238ed53e822a632f85b19e070928847de3e05e670",
    "parent_trajectory_manifest": "PASS_130_OF_130",
    "independent_observer_recompute": {
      "k0": "PASS_EXACT_OBSERVER_SHA",
      "k64": "PASS_EXACT_OBSERVER_SHA",
      "k128": "PASS_EXACT_OBSERVER_SHA"
    },
    "controller_stderr_bytes": 0,
    "prelaunch_freeze_verify_stderr_bytes": 0
  },
  "scientific_result_supported": {
    "supported": true,
    "statement": "There exist recurrent one-step action-labelled transition-refined relational types under the V1.5 C1 definition. This is retrospective evidence only and is not a mature higher-order node result.",
    "k128_selected_exact": 941,
    "k128_C1_classes": 275,
    "k128_exact_to_C1_compression": 3.421818181818182,
    "k128_multi_realization_C1_classes": 39,
    "k128_largest_C1_exact_realizations": 257
  },
  "critical_scientific_limitation": {
    "issue": "ONE_STEP_REFINEMENT_NOT_FIXED_POINT",
    "description": "C1(x)=hash(C0,R_to_C0,M_to_C0) performs only one partition-refinement step. It does not iterate successor coloring until the partition stabilizes. Therefore equality of C1 does not imply equality of transitions to C1, let alone arbitrary-depth future substitutability.",
    "empirical_C2_counterexamples_at_k128": [
      {
        "C1": "afbe0c7ce7bf9ea5136b809fd4cc1213b722bb2019e73bc3cfd731a1428e1ec9",
        "class_members": 2,
        "C2_reach_sizes": [6,10],
        "verdict": "SPLITS"
      },
      {
        "C1": "81f70cff92bb12a89e80fcb286d32e7da5cb8d218992d4d0731d70de56e89d33",
        "class_members": 257,
        "C2_reach_sizes": [6,10],
        "verdict": "SPLITS_IN_TARGETED_MEMBER_PAIR"
      },
      {
        "C1": "73a1d4b07126aaf68e6ae29ad8f75940bd3b54b1c4a736165715a4fd0ccf9948",
        "class_members": 108,
        "C2_reach_sizes": [5,8],
        "verdict": "SPLITS_IN_TARGETED_MEMBER_PAIR"
      }
    ]
  },
  "retrospective_recurrence_context": {
    "official_recurrent_C1_count": 5815,
    "median_longest_contiguous_span": 3,
    "mean_longest_contiguous_span": 5.742218400687876,
    "classes_with_span_at_least_48": 52,
    "classes_with_span_129": 10,
    "recurrent_classes_with_multi_realization_sometime": 2624,
    "recurrent_classes_with_multi_realization_on_adjacent_k": 1133,
    "interpretation": "The headline count 5815 is dominated by short recurrence; persistence should be judged by the frozen prospective gate, not raw recurrence count."
  },
  "prospective_gate_dry_check": {
    "note": "Retrospective diagnostic only; not graduation.",
    "window_73_120_pass_A_to_F": 1,
    "window_81_128_pass_A_to_F": 0,
    "interpretation": "A strong class existed in the 48-level window ending k120 but no class satisfies even A-F in the terminal k81-k128 window. This reinforces that candidate turnover remains active."
  },
  "spec_implementation_issues": [
    {
      "severity": "HIGH",
      "issue": "SOURCE_INTEGRITY_FAIL_CLOSED_INCOMPLETE",
      "detail": "Frozen Section 2 requires verifying the V1.3 freeze SHA and complete parent panels. source_integrity() verifies V1.2/V1.3 science hashes and file existence, but not the V1.3 freeze SHA and not parent checkpoint hashes. Independent audit verification of the existing parent manifest passed 130/130, so this is a guardrail defect, not evidence of corrupted science."
    },
    {
      "severity": "MEDIUM",
      "issue": "RETROSPECTIVE_STATUS_LOGIC_WEAKER_THAN_SECTION_14",
      "detail": "retrospective_summary() marks a recurrent C1 after any 2-level contiguous recurrence, without requiring >=2 exact realizations as Section 14 states. The substantive existence claim still survives because 2624 recurrent classes have multiple realizations at least once and 1133 do so at adjacent k, but the status implementation should be corrected."
    },
    {
      "severity": "MEDIUM",
      "issue": "TRANSITIVE_RUNTIME_DEPENDENCY_NOT_IN_FREEZE_MANIFEST",
      "detail": "The frozen V1.5 bundle omitted scout2_relational_longitudinal_v1_1.py. The official runtime copied the exact parent dependency and recorded SHA e46fcf445cc32cf844f28f5511bb7a9170369e3f1a710bfd23787751b8e5ef19. No result mismatch was found, but future freezes should include and hash all transitive scientific dependencies."
    },
    {
      "severity": "LOW",
      "issue": "SYNTHETIC_TEST_COVERAGE_NARROW",
      "detail": "The synthetic test checks reachability/multiplicity splitting and canonical order only. It does not exercise source-integrity guards, recurrence status, action-label collision handling, or recursive refinement."
    }
  ],
  "recommended_next_step": {
    "action": "DO_NOT_LAUNCH_K129_PLUS_WITH_C1_AS_GRADUATION_IDENTITY",
    "proposal": "Freeze a fixed-point transition partition observer: start from C0 and repeatedly define C_{n+1} from C_n plus action-labelled successor C_n profiles (with the frozen exact-child multiplicity semantics) until no class splits. Treat the stabilized partition as the candidate behavioral color. Replay only the observer on existing k0-k128, audit it, then freeze the unseen k129+ continuation.",
    "no_regeneration_k0_k128": true,
    "geometry_claims": "NOT_AUTHORIZED"
  }
}
